"""Generate (and serve) the PAC file that sends only the listed domains through the relay."""
import http.server
from typing import List

from .config import Config

TEMPLATE = """\
// generated by gatewatch - do not edit by hand
function FindProxyForURL(url, host) {{
  host = host.toLowerCase();
  if (isPlainHostName(host) ||
      isInNet(host, "10.0.0.0", "255.0.0.0") ||
      isInNet(host, "172.16.0.0", "255.240.0.0") ||
      isInNet(host, "192.168.0.0", "255.255.0.0") ||
      isInNet(host, "127.0.0.0", "255.0.0.0")) {{
    return "DIRECT";
  }}
  var domains = [{domains}];
  for (var i = 0; i < domains.length; i++) {{
    var d = domains[i];
    if (host == d || dnsDomainIs(host, "." + d)) {{
      // NO "; DIRECT" fallback on purpose: if the relay is down the page must fail loudly,
      // not quietly load over your real IP and show the region stub.
      return "PROXY {relay}";
    }}
  }}
  return "DIRECT";
}}
"""


def build(cfg: Config) -> str:
    hosts: List[str] = [h.lstrip(".").lower() for h in cfg.lst("pac", "hosts")]
    return TEMPLATE.format(domains=", ".join('"%s"' % h for h in hosts), relay=cfg.get("pac", "relay"))


def serve(cfg: Config, port: int) -> None:
    body = build(cfg).encode()

    class Handler(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            self.send_response(200)
            self.send_header("Content-Type", "application/x-ns-proxy-autoconfig")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-cache")
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, *a):
            pass

    print("serving the PAC file on http://0.0.0.0:%d/gatewatch.pac" % port)
    http.server.ThreadingHTTPServer(("0.0.0.0", port), Handler).serve_forever()
